const items = $input.all();

return items.map(item => {
  // Webhook node puts your POST JSON into item.json.body
  const body = item.json.body || item.json || {};

  const text = body.text || '';
  const image = body.image || null;      // base64 string (if any)
  const mimeType = body.mimeType || null;

  const newItem = {
    json: {
      text,
      hasImage: !!image
    }
  };

  // If an image was sent, convert base64 -> binary for OCR node
  if (image) {
    const buffer = Buffer.from(image, 'base64');
    newItem.binary = {
      data: {
        data: buffer,
        mimeType: mimeType || 'image/jpeg',
        fileName: 'upload.' + (mimeType ? mimeType.split('/')[1] : 'jpg')
      }
    };
  }

  return newItem;
});

// Extract OCR text only
const ocrResult = $input.item.json;

let extractedText = '';

if (ocrResult.ParsedResults && ocrResult.ParsedResults.length > 0) {
  extractedText = ocrResult.ParsedResults[0].ParsedText || '';
}

return {
  text: extractedText,
  source: 'image'
};

// Extract text from web form payload
const text = $json.text || '';

return {
  text,
  source: 'text'
};

// Parse LLM JSON and build event object

const gptResponse = $json.text;

if (!gptResponse) {
  return {
    error: true,
    message: "No response from AI model. Please try again."
  };
}

try {
  // Clean code fences if any (```json ... ```)
  let jsonStr = gptResponse.trim();
  jsonStr = jsonStr
    .replace(/^```json/i, "")
    .replace(/^```/, "")
    .replace(/```$/, "")
    .trim();

  const eventData = JSON.parse(jsonStr);

  // Validate required fields
  if (!eventData.title || !eventData.start) {
    return {
      error: true,
      message:
        "Missing required details. Please provide at least: title and date/time."
    };
  }

  // Build dates
  const timezone = eventData.timezone || "Asia/Ho_Chi_Minh";

  // For VN time (UTC+7)
  const tzOffset = "+07:00";

  function makeZonedDate(str) {
    // If string already has Z or an offset, use as-is
    if (/[zZ]|[+\-]\d\d:\d\d$/.test(str)) {
      return new Date(str);
    }
    // Otherwise, treat it as local VN time
    return new Date(`${str}${tzOffset}`);
  }

  const startDate = makeZonedDate(eventData.start);
  const endDate = eventData.end
    ? makeZonedDate(eventData.end)
    : new Date(startDate.getTime() + 60 * 60 * 1000);

  return {
    error: false,
    title: eventData.title,
    start: startDate.toISOString(),
    end: endDate.toISOString(),
    location: eventData.location || "",
    description: eventData.description || "",
    timezone,
    displayStart: startDate.toLocaleString("en-GB", {
      timeZone: timezone,
      day: "2-digit",
      month: "long",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit"
    }),
    displayEnd: endDate.toLocaleString("en-GB", {
      timeZone: timezone,
      hour: "2-digit",
      minute: "2-digit"
    })
  };
} catch (error) {
  return {
    error: true,
    message:
      `Error parsing AI response: ${error.message}. Please try again with clearer event details.`
  };
}
